    // if (!e==1 || false) return
    list.push({
        "ChapterName": a || "",
        "isVolume": b || false,
        "chapterUrl": c ? b64Url(
          JSON.stringify({
            source: "qd",
            cid: c || null,
            isVip: e==1 || false,
            isPay: f==1 || false,
            ccid: null,
            cbid: null
          })) : "",
        "ChapterInfo": d || "",
        "isVip": e==1 || false,
        "isPay": f==1 || false
    });
}


let t_List = $.Volumes;
for (let $$ of t_List) {
	  let Vc = $$.VolumeCode;
    v_Names[Vc] = $$.VolumeName;
    c_Json[Vc] = [];
    if (t_List.length > 1) {
        push(Vc, $$.VolumeName, true);
    }
}


t_List = $.Chapters.slice(1);
